import { DirectionEnum } from '06_shared/types/types';
// Напрям угоди чи сигналу. Окремий тон від profit/loss: колір той самий, але
// «шорт» і «збиток» — різні речі, і схема ріст/падіння може їх розвести.
export const directionTone = (direction) => {
    switch (direction) {
        case DirectionEnum.BUY:
            return 'long';
        case DirectionEnum.SELL:
            return 'short';
        default:
            return 'neutral';
    }
};
