export const getBinanceDescriptionByCode = (code, symbol_pair) => {
    try {
        const response = binanceCodes[code];
        return response
            ? { ...response, description: [...response.description, symbol_pair] }
            : {
                description: ['Unknown error', symbol_pair, `${code}`],
                isReturn: true,
                isShowed: true,
                type: 'Error',
            };
    }
    catch {
        return {
            description: ['Unknown error', symbol_pair, `${code}`],
            isReturn: true,
            isShowed: true,
            type: 'Error',
        };
    }
};
