import { useCreateTradeClientMutation } from '../api/signalApi';
import { useGetPinCodeByPlatformUUID } from '05_entities/pinCode';
import { DirectionEnum } from '06_shared/types/types';
import { TradeTokenLevelEnum, useGetTradeTokenByPlatformUUID, updateTradeTokenMessage, } from '05_entities/tradeToken';
import { useGetPlatformPreferences } from '05_entities/platformPreferences';
import { useCallback, useState } from 'react';
import { notificationActions } from '05_entities/notification';
import { NOTIFICATION_KEYS } from '06_shared/constants/notificationKeys';
import { useAppDispatch } from '06_shared/hooks/useAppDispatch';
import { BinanceFAPI } from '06_shared/api/binanceFAPI';
import { getBinanceDescriptionByCode } from '06_shared/utils/getBinanceDescriptionByCode';
import { decodeString } from '06_shared/utils/cryptoJSUtils';
import { serviceErrorHandler } from '06_shared/utils/serviceErrorHandler';
import { useGetMe } from '06_shared/hooks/useGetMe';
const useCreateTradeClient = (signal) => {
    const dispatch = useAppDispatch();
    const pin_code = useGetPinCodeByPlatformUUID(signal.platform_uuid);
    const trade_token = useGetTradeTokenByPlatformUUID(signal.platform_uuid);
    const platform_preferences = useGetPlatformPreferences(signal.platform_uuid);
    const user = useGetMe();
    const [isLoadingInner, setIsLoadingInner] = useState(false);
    const [executor, { isLoading, },] = useCreateTradeClientMutation();
    const createTradeClient = useCallback(async () => {
        if (!pin_code)
            return;
        if (!trade_token)
            return;
        if (trade_token.level !== TradeTokenLevelEnum.TRADE_AVAILABLE)
            return;
        if (!platform_preferences)
            return;
        if (!user) {
            dispatch(notificationActions.addNotificationItem({
                type: 'Error',
                description: [NOTIFICATION_KEYS.CURRENT_USER_NOT_FOUND, signal.symbol.symbol_pair],
            }));
            return;
        }
        const trade_token_encoded_string = localStorage.getItem(signal.platform_uuid);
        if (!trade_token_encoded_string) {
            dispatch(notificationActions.addNotificationItem({
                type: 'Error',
                description: [NOTIFICATION_KEYS.TRADE_TOKEN_NOT_FOUND, signal.symbol.symbol_pair],
            }));
            return;
        }
        try {
            setIsLoadingInner(true);
            const key = `${pin_code}${user.user_trade_token_key}`;
            const trade_token_decoded_string = await decodeString(trade_token_encoded_string, key);
            const trade_token_decoded_dict = JSON.parse(trade_token_decoded_string);
            await updateTradeTokenMessage(signal.platform_uuid, trade_token_decoded_dict, key, `Creating trade ${signal.symbol.symbol_pair} ${signal.signal_direction_created}`);
            const binance_fapi = new BinanceFAPI(trade_token_decoded_dict.api_key, trade_token_decoded_dict.api_secret);
            const resLeverage = await binance_fapi.changeInitLeverage(signal.symbol.symbol_pair, platform_preferences.trade_leverage.toString());
            if (resLeverage.code) {
                const descLeverage = getBinanceDescriptionByCode(resLeverage.code, signal.symbol.symbol_pair);
                descLeverage.isShowed && dispatch(notificationActions.addNotificationItem({
                    ...descLeverage,
                }));
                if (descLeverage.isReturn) {
                    return;
                }
            }
            const resMargin = await binance_fapi.changeMarginType(signal.symbol.symbol_pair, 'ISOLATED');
            if (resMargin.code) {
                const descMargin = getBinanceDescriptionByCode(resMargin.code, signal.symbol.symbol_pair);
                descMargin.isShowed && dispatch(notificationActions.addNotificationItem({
                    ...descMargin,
                }));
                if (descMargin.isReturn) {
                    return;
                }
            }
            const resPosition = await binance_fapi.changePositionMode('false');
            if (resPosition.code) {
                const descPosition = getBinanceDescriptionByCode(resPosition.code, signal.symbol.symbol_pair);
                descPosition.isShowed && dispatch(notificationActions.addNotificationItem({
                    ...descPosition,
                }));
                if (descPosition.isReturn) {
                    return;
                }
            }
            let trade_quantity = platform_preferences.trade_margin
                * platform_preferences.trade_leverage
                / signal.signal_price_enter;
            trade_quantity = Number(trade_quantity.toFixed(signal.symbol.symbol_quantity_precision));
            let trade_stop_loss_price = 0;
            if (signal.signal_direction_created === DirectionEnum.BUY) {
                trade_stop_loss_price = (signal.signal_price_enter * (100 - (platform_preferences.trade_stop_loss_percent
                    / platform_preferences.trade_leverage))) / 100;
            }
            else if (signal.signal_direction_created === DirectionEnum.SELL) {
                trade_stop_loss_price = (signal.signal_price_enter * (100 + (platform_preferences.trade_stop_loss_percent
                    / platform_preferences.trade_leverage))) / 100;
            }
            trade_stop_loss_price = Number(trade_stop_loss_price.toFixed(signal.symbol.symbol_price_precision));
            const resStopOrder = await binance_fapi.newStopOrder(signal.symbol.symbol_pair, signal.signal_direction_created === DirectionEnum.BUY
                ? DirectionEnum.SELL
                : DirectionEnum.BUY, trade_stop_loss_price, trade_quantity);
            if (resStopOrder.code) {
                const descStopOrder = getBinanceDescriptionByCode(resStopOrder.code, signal.symbol.symbol_pair);
                descStopOrder.isShowed && dispatch(notificationActions.addNotificationItem({
                    ...descStopOrder
                }));
                if (descStopOrder.isReturn) {
                    return;
                }
            }
            const resTradeOrder = await binance_fapi.newTradeOrder(signal.symbol.symbol_pair, signal.signal_direction_created, trade_quantity);
            if (resTradeOrder.code) {
                const descTradeOrder = getBinanceDescriptionByCode(resTradeOrder.code, signal.symbol.symbol_pair);
                descTradeOrder.isShowed && dispatch(notificationActions.addNotificationItem({
                    ...descTradeOrder,
                }));
                if (descTradeOrder.isReturn) {
                    return;
                }
            }
            else {
                dispatch(notificationActions.addNotificationItem({
                    type: 'Success',
                    description: [NOTIFICATION_KEYS.TRADE_OPENED],
                }));
            }
            const positionRisk = await binance_fapi.getPositionRisk(signal.symbol.symbol_pair);
            const trade_open_price = parseFloat(positionRisk[0].entryPrice); // or try breakEvenPrice
            const createTradePayload = {
                signal_uuid: signal.signal_uuid,
                trade_margin: platform_preferences.trade_margin,
                trade_leverage: platform_preferences.trade_leverage,
                trade_stop_loss_percent: platform_preferences.trade_stop_loss_percent,
                trade_take_profit_percent: platform_preferences.trade_take_profit_percent,
                trade_treiling_stop_percent: platform_preferences.trade_treiling_stop_percent,
                trade_quantity,
                trade_open_price,
                trade_order_id: String(resTradeOrder.clientOrderId),
                trade_stop_order_id: String(resStopOrder.clientAlgoId),
            };
            executor(createTradePayload);
        }
        catch (e) {
            throw serviceErrorHandler(e);
        }
        finally {
            setIsLoadingInner(false);
        }
    }, [
        dispatch,
        executor,
        pin_code,
        platform_preferences,
        signal.platform_uuid,
        signal.signal_direction_created,
        signal.signal_price_enter,
        signal.signal_uuid,
        signal.symbol.symbol_pair,
        signal.symbol.symbol_price_precision,
        signal.symbol.symbol_quantity_precision,
        trade_token,
        user
    ]);
    return {
        createTradeClient,
        isLoading: isLoading || isLoadingInner,
    };
};
export { useCreateTradeClient };
