import { useGetPinCodeByPlatformUUID } from '05_entities/pinCode';
import { TradeTokenLevelEnum, useGetTradeTokenByPlatformUUID, updateTradeTokenMessage, } from '05_entities/tradeToken';
import { useGetPlatformPreferences } from '05_entities/platformPreferences';
import { useCallback, useState } from 'react';
import { notificationActions } from '05_entities/notification';
import { NOTIFICATION_KEYS } from '06_shared/constants/notificationKeys';
import { useAppDispatch } from '06_shared/hooks/useAppDispatch';
import { BinanceFAPI } from '06_shared/api/binanceFAPI';
import { useCloseTradeClientMutation } from '../api/tradeApi';
import { DirectionEnum } from '05_entities/signal';
import { getBinanceDescriptionByCode } from '06_shared/utils/getBinanceDescriptionByCode';
import { decodeString } from '06_shared/utils/cryptoJSUtils';
import { serviceErrorHandler } from '06_shared/utils/serviceErrorHandler';
import { useGetMe } from '06_shared/hooks/useGetMe';
const useCloseTradeClient = (trade) => {
    const dispatch = useAppDispatch();
    const pin_code = useGetPinCodeByPlatformUUID(trade.platform_uuid);
    const trade_token = useGetTradeTokenByPlatformUUID(trade.platform_uuid);
    const platform_preferences = useGetPlatformPreferences(trade.platform_uuid);
    const user = useGetMe();
    const [isLoadingInner, setIsLoadingInner] = useState(false);
    const [executor, { isLoading, },] = useCloseTradeClientMutation();
    const closeTradeClient = useCallback(async (trade_status) => {
        if (!pin_code)
            return;
        if (!trade_token)
            return;
        if (trade_token.level !== TradeTokenLevelEnum.TRADE_AVAILABLE)
            return;
        if (!platform_preferences)
            return;
        if (!user) {
            dispatch(notificationActions.addNotificationItem({
                type: 'Error',
                description: [NOTIFICATION_KEYS.CURRENT_USER_NOT_FOUND, trade.symbol.symbol_pair],
            }));
            return;
        }
        const trade_token_encoded_string = localStorage.getItem(trade.platform_uuid);
        if (!trade_token_encoded_string) {
            dispatch(notificationActions.addNotificationItem({
                type: 'Error',
                description: [NOTIFICATION_KEYS.TRADE_TOKEN_NOT_FOUND, trade.symbol.symbol_pair],
            }));
            return;
        }
        try {
            setIsLoadingInner(true);
            const key = `${pin_code}${user.user_trade_token_key}`;
            const trade_token_decoded_string = await decodeString(trade_token_encoded_string, key);
            const trade_token_decoded_dict = JSON.parse(trade_token_decoded_string);
            await updateTradeTokenMessage(trade.platform_uuid, trade_token_decoded_dict, key, `Closing trade ${trade.symbol.symbol_pair} ${trade.trade_direction}`);
            const binance_fapi = new BinanceFAPI(trade_token_decoded_dict.api_key, trade_token_decoded_dict.api_secret);
            const resLeverage = await binance_fapi.changeInitLeverage(trade.symbol.symbol_pair, platform_preferences.trade_leverage.toString());
            if (resLeverage.code) {
                const descLeverage = getBinanceDescriptionByCode(resLeverage.code, trade.symbol.symbol_pair);
                descLeverage.isShowed && dispatch(notificationActions.addNotificationItem({
                    ...descLeverage,
                }));
                if (descLeverage.isReturn) {
                    return;
                }
            }
            const resMargin = await binance_fapi.changeMarginType(trade.symbol.symbol_pair, 'ISOLATED');
            if (resMargin.code) {
                const descMargin = getBinanceDescriptionByCode(resMargin.code, trade.symbol.symbol_pair);
                descMargin.isShowed && dispatch(notificationActions.addNotificationItem({
                    ...descMargin,
                }));
                if (descMargin.isReturn) {
                    return;
                }
            }
            const resPosition = await binance_fapi.changePositionMode('false');
            if (resPosition.code) {
                const descPosition = getBinanceDescriptionByCode(resPosition.code, trade.symbol.symbol_pair);
                descPosition.isShowed && dispatch(notificationActions.addNotificationItem({
                    ...descPosition,
                }));
                if (descPosition.isReturn) {
                    return;
                }
            }
            const resTradeOrder = await binance_fapi.newTradeOrder(trade.symbol.symbol_pair, trade.trade_direction === DirectionEnum.BUY
                ? DirectionEnum.SELL
                : DirectionEnum.BUY, trade.trade_quantity);
            if (resTradeOrder.code) {
                const descTradeOrder = getBinanceDescriptionByCode(resTradeOrder.code, trade.symbol.symbol_pair);
                descTradeOrder.isShowed && dispatch(notificationActions.addNotificationItem({
                    ...descTradeOrder
                }));
            }
            else {
                dispatch(notificationActions.addNotificationItem({
                    type: 'Success',
                    description: [NOTIFICATION_KEYS.TRADE_CLOSED],
                }));
            }
            const resCancelOrder = await binance_fapi.cancelOrder(trade.trade_stop_order_id);
            if (resCancelOrder.code) {
                const descCancelOrder = getBinanceDescriptionByCode(resCancelOrder.code, trade.symbol.symbol_pair);
                descCancelOrder.isShowed && dispatch(notificationActions.addNotificationItem({
                    ...descCancelOrder
                }));
            }
            else {
                dispatch(notificationActions.addNotificationItem({
                    type: 'Success',
                    description: [NOTIFICATION_KEYS.POSITION_STOP_LOSS_CANCELLED],
                }));
            }
            const closeTradePayload = {
                trade_uuid: trade.trade_uuid,
                trade_status: trade_status,
            };
            executor(closeTradePayload);
        }
        catch (e) {
            throw serviceErrorHandler(e);
        }
        finally {
            setIsLoadingInner(false);
        }
    }, [
        dispatch,
        executor,
        pin_code,
        platform_preferences,
        trade.platform_uuid,
        trade.symbol.symbol_pair,
        trade.trade_direction,
        trade.trade_quantity,
        trade.trade_stop_order_id,
        trade.trade_uuid,
        trade_token,
        user,
    ]);
    return {
        closeTradeClient,
        isLoading: isLoading || isLoadingInner,
    };
};
export { useCloseTradeClient };
