export class BinanceFAPI {
    constructor(api_key, api_secret) {
        this.base_url = 'https://fapi.binance.com';
        this.headers = {
            'X-MBX-APIKEY': '',
            'Content-Type': 'application/json;charset=utf-8',
        };
        this.params = {};
        this.api_key = '';
        this.api_secret = '';
        this.headers['X-MBX-APIKEY'] = api_key;
        this.api_key = api_key;
        this.api_secret = api_secret;
    }
    async hashing(query_string) {
        const [{ default: HmacSHA256 }, Hex] = await Promise.all([
            import('crypto-js/hmac-sha256'),
            import('crypto-js/enc-hex'),
        ]);
        return HmacSHA256(query_string, this.api_secret).toString(Hex);
    }
    getTimestamp() {
        return Math.floor(new Date().getTime()).toString();
    }
    async prepareParams(payload) {
        const params = {
            timestamp: this.getTimestamp(),
            recvWindow: '10000',
            ...payload,
        };
        // Саме encodeURIComponent, а не URLSearchParams: той кодує пробіл як «+»
        // і екранує ! ' ( ) ~, тож підпис на таких значеннях змінився б.
        let query_string = Object.entries(params)
            .map(([key, value]) => `${encodeURIComponent(key)}=${encodeURIComponent(value)}`)
            .join('&');
        query_string = query_string.replace(/%27/g, '%22');
        const signature = await this.hashing(query_string);
        params['signature'] = signature;
        this.params = params;
    }
    async sendRequest(path, method) {
        const options = {
            method: method,
            headers: this.headers,
        };
        const queryString = new URLSearchParams(this.params).toString();
        const response = await fetch(`${this.base_url}${path}?${queryString}`, options);
        return response.json();
    }
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    async changeInitLeverage(symbol, leverage) {
        try {
            await this.prepareParams({ symbol, leverage });
            return await this.sendRequest('/fapi/v1/leverage', 'POST');
        }
        catch (error) {
            console.error(error);
            throw new Error('changeInitLeverage');
        }
    }
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    async getAccount() {
        try {
            await this.prepareParams({});
            return await this.sendRequest('/fapi/v2/account', 'GET');
        }
        catch (error) {
            console.error(error);
            throw new Error('getAccount');
        }
    }
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    async getPositionRisk(symbol) {
        try {
            await this.prepareParams({ symbol });
            return await this.sendRequest('/fapi/v2/positionRisk', 'GET');
        }
        catch (error) {
            console.error(error);
            throw new Error('getPositionRisk');
        }
    }
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    async changeMarginType(symbol, marginType) {
        try {
            await this.prepareParams({ symbol, marginType });
            return await this.sendRequest('/fapi/v1/marginType', 'POST');
        }
        catch (error) {
            console.error(error);
            throw new Error('changeMarginType');
        }
    }
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    async changePositionMode(dualSidePosition) {
        try {
            await this.prepareParams({ dualSidePosition });
            return await this.sendRequest('/fapi/v1/positionSide/dual', 'POST');
        }
        catch (error) {
            console.error(error);
            throw new Error('changePositionMode');
        }
    }
    async newStopOrder(symbol, side, price, quantity) {
        try {
            await this.prepareParams({
                algoType: 'CONDITIONAL',
                symbol,
                side: side.toUpperCase(),
                type: 'STOP_MARKET',
                triggerPrice: String(price),
                quantity: String(quantity),
            });
            return await this.sendRequest('/fapi/v1/algoOrder', 'POST');
        }
        catch (error) {
            console.error(error);
            throw new Error('newStopOrder');
        }
    }
    async newTradeOrder(symbol, side, quantity
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    ) {
        try {
            await this.prepareParams({
                symbol,
                side: side.toUpperCase(),
                type: 'MARKET',
                quantity: String(quantity),
            });
            return await this.sendRequest('/fapi/v1/order', 'POST');
        }
        catch (error) {
            console.error(error);
            throw new Error('newTradeOrder');
        }
    }
    async cancelOrder(clientalgoid
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    ) {
        try {
            await this.prepareParams({
                clientalgoid
            });
            return await this.sendRequest('/fapi/v1/algoOrder', 'DELETE');
        }
        catch (error) {
            console.error(error);
            throw new Error('cancelOrder');
        }
    }
}
