import { encodeString } from '06_shared/utils/cryptoJSUtils';
export const updateTradeTokenMessage = async (platform_uuid, trade_token_decoded_dict, key, message) => {
    const new_trade_token_decoded_dict = {
        ...trade_token_decoded_dict,
        updated_at: new Date().toISOString(),
        message,
    };
    const trade_token_decoded_string = JSON.stringify(new_trade_token_decoded_dict);
    const trade_token_encoded_string = await encodeString(trade_token_decoded_string, key);
    await localStorage.setItem(platform_uuid, trade_token_encoded_string);
};
