import { createSlice } from '@reduxjs/toolkit';
const initialState = {
    is_visible: false,
};
export const signalInfoHeaderSlice = createSlice({
    name: 'signalInfoHeader',
    initialState,
    reducers: {
        setSignalInfoHeaderSchema: (state, action) => {
            return { is_visible: true, ...action.payload };
        },
        removeSignalInfoHeaderSchema() {
            return { is_visible: false };
        },
        resetSignalInfoHeaderSlice() {
            return initialState;
        },
    }
});
export const { actions: signalInfoHeaderActions } = signalInfoHeaderSlice;
export const { reducer: signalInfoHeaderReducer } = signalInfoHeaderSlice;
