import { useEffect } from 'react';
import { useAppDispatch } from '06_shared/hooks/useAppDispatch';
import { websocketTransport } from '06_shared/lib/websocket';
import { WSEventEnum } from '06_shared/types/types';
import { tradeActions } from '../slice/tradeSlice';
// Лишаємо підписку тут, а не в onCacheEntryAdded: список читає звичайний
// слайс через мемоїзований селектор, і переїзд скасував би ту оптимізацію.
const useSubscribeTradeUpdates = () => {
    const dispatch = useAppDispatch();
    useEffect(() => {
        return websocketTransport.on(WSEventEnum.TRADE_UPDATED_RESPONSE_FROM_CORE, (message) => {
            const payload = message;
            dispatch(tradeActions.updateTradeAfterCalculate(payload));
        });
    }, [dispatch]);
};
export { useSubscribeTradeUpdates };
