import { useCallback } from 'react';
import { useTradeSideExecutor } from '05_entities/tradePreferences';
import { useAppDispatch } from '06_shared/hooks/useAppDispatch';
import { useCloseTradeServer } from '../hooks/useCloseTradeServer';
import { useCloseTradeClient } from '../hooks/useCloseTradeClient';
import { tradeApi } from '../api/tradeApi';
const useCloseTradeItem = (trade) => {
    const dispatch = useAppDispatch();
    const { closeTradeServer, isLoading: isLoadingServer, } = useCloseTradeServer(trade);
    const { closeTradeClient, isLoading: isLoadingClient, } = useCloseTradeClient(trade);
    const closeTradeSide = useTradeSideExecutor(closeTradeClient, closeTradeServer);
    const closeTradeItem = useCallback(async (trade_status) => {
        try {
            await closeTradeSide(trade_status);
            setTimeout(() => {
                dispatch(tradeApi.util.invalidateTags(['tradeList']));
            }, 1000);
        }
        catch (e) {
            console.log(e);
        }
    }, [closeTradeSide, dispatch]);
    return {
        closeTradeItem,
        isLoadingCloseTradeItem: isLoadingServer || isLoadingClient,
    };
};
export { useCloseTradeItem, };
