import { useCallback, useEffect, useState } from 'react';
import { useAppDispatch } from '06_shared/hooks/useAppDispatch';
import { websocketTransport } from '06_shared/lib/websocket';
import { WSEventEnum } from '06_shared/types/types';
import { tradeActions, useGetTradeUuidBySymbolUuidDict } from '05_entities/trade';
import { useGetSymbolPriceCurrent } from '05_entities/symbol';
import { signalActions, } from '05_entities/signal';
// Хук оркеструє одразу три сутності, а така міжсутнісна координація за
// FSD належить фічі, не сутності. Попри назву це робоча функціональність
// — двосторонній обмін ціною й сигналами, а не відлагоджувальне сміття.
const useUpdateSignalTest = () => {
    const dispatch = useAppDispatch();
    const trade_uuid_by_symbol_uuid_dict = useGetTradeUuidBySymbolUuidDict();
    const symbol_price_current = useGetSymbolPriceCurrent();
    const [signalItemTemp, setSignalItemTemp] = useState(undefined);
    const sendUpdateTradeBySymbolPrice = useCallback((trade_uuid_by_symbol_uuid_dict_internal, symbol_price_current_internal) => {
        if (!trade_uuid_by_symbol_uuid_dict_internal)
            return;
        if (!symbol_price_current_internal)
            return;
        const trade_uuid = trade_uuid_by_symbol_uuid_dict_internal[symbol_price_current_internal.symbol_uuid];
        if (!trade_uuid)
            return;
        websocketTransport.send(WSEventEnum.UPDATE_TRADE_BY_CURRENT_PRICE_FROM_CLIENT, {
            trade_uuid,
            symbol_uuid: symbol_price_current_internal.symbol_uuid,
        });
    }, []);
    const sendAddSignalBySignalTemp = useCallback((trade_uuid_by_symbol_uuid_dict_internal, signalItemInternal) => {
        if (!signalItemInternal)
            return;
        const trade_uuid = trade_uuid_by_symbol_uuid_dict_internal[signalItemInternal.symbol_uuid];
        if (trade_uuid) {
            dispatch(tradeActions.updateTradeAfterSignalItem(signalItemInternal));
        }
        else {
            dispatch(signalActions.addSignalItem(signalItemInternal));
        }
        setSignalItemTemp(undefined);
    }, [dispatch]);
    useEffect(() => {
        return websocketTransport.on(WSEventEnum.SIGNAL_FROM_CORE, (message) => {
            const payload = message;
            setSignalItemTemp({
                ...payload.signal_by_uuid,
                trend_moment: payload.trend_moment,
            });
        });
    }, []);
    useEffect(() => {
        sendUpdateTradeBySymbolPrice(trade_uuid_by_symbol_uuid_dict, symbol_price_current);
    }, [sendUpdateTradeBySymbolPrice, trade_uuid_by_symbol_uuid_dict, symbol_price_current]);
    useEffect(() => {
        sendAddSignalBySignalTemp(trade_uuid_by_symbol_uuid_dict, signalItemTemp);
    }, [sendAddSignalBySignalTemp, trade_uuid_by_symbol_uuid_dict, signalItemTemp]);
};
export { useUpdateSignalTest };
