import { useEffect, useState } from 'react';
export const useElapsedSeconds = (resetKey) => {
    const [clock, setClock] = useState({ key: resetKey, start: 0, now: 0 });
    // Старт читаємо в ефекті (у рендері годинник читати не можна), стан
    // оновлює лише колбек інтервалу. Нове значення — лише коли щось змінилось:
    // із замороженим Date (Storybook) тік не перерендерює компонент.
    useEffect(() => {
        const start = Date.now();
        const timer = setInterval(() => {
            const now = Date.now();
            setClock((prev) => (Object.is(prev.key, resetKey) && prev.start === start && prev.now === now
                ? prev
                : { key: resetKey, start, now }));
        }, 1000);
        return () => clearInterval(timer);
    }, [resetKey]);
    // Ключ щойно змінився, а перший тік нового відліку ще не прийшов — це нуль,
    // а не секунди попереднього статусу.
    if (!Object.is(clock.key, resetKey))
        return 0;
    return Math.max(0, Math.floor((clock.now - clock.start) / 1000));
};
