import { createSelector } from '@reduxjs/toolkit';
import { useAppSelector } from '06_shared/hooks/useAppSelector';
const EMPTY_LIST = [];
// Голий useAppSelector з Object.values() створював новий масив на кожен
// рендер, і список перемальовувався від будь-якого чужого dispatch.
// Селектор типізовано локальною схемою, щоб не перетнути межу шарів.
const selectTradeList = createSelector((trade) => trade?.trade_by_uuid_dict, (trade_by_uuid_dict) => trade_by_uuid_dict ? Object.values(trade_by_uuid_dict) : EMPTY_LIST);
const useGetTradeList = () => {
    const trade = useAppSelector((state) => state.trade);
    return selectTradeList(trade);
};
export { useGetTradeList };
